def _cross(template: str, *pools: tuple[str, ...]) -> tuple[str, ...]:
    """Build a grammatical reservoir from independently authored fragments."""

    return tuple(template.format(*parts) for parts in product(*pools))


def _clauses(
    verbs: tuple[str, ...],
    objects: tuple[str, ...],
) -> tuple[str, ...]:
    return tuple(f"{verb} {object}" for verb, object in product(verbs, objects))


def _aligned_sentences(*clause_pools: tuple[str, ...]) -> tuple[str, ...]:
    """Align equally sized clause reservoirs so every sentence stays balanced."""

    size = len(clause_pools[0])
    if any(len(pool) != size for pool in clause_pools):
        raise ValueError("aligned surface clause pools must have equal sizes")
    return tuple(
        " ".join(f"{pool[index]}." for pool in clause_pools) for index in range(size)
    )


def _planning_valid_records(
    option: str,
    cost: str,
    *,
    duration: int,
) -> tuple[str, ...]:
    """Return full alternatives without a shared eight-word cost template."""

    value = f"{{{option}}}"
    price = f"${{{cost}}}"
    return (
        f"{value}; it costs {price}, takes {duration} days, and meets every requirement.",
        f"{value}. At {price}, the work finishes in {duration} days with all conditions met.",
        f"{value}, priced at {price} for a {duration}-day delivery that satisfies every condition.",
        f"{value}; the {duration}-day plan uses {price} and clears the full requirement set.",
        f"{value}. Its {price} cost and {duration}-day schedule both remain within the stated limits.",
        f"{value}; budget use is {price}, completion takes {duration} days, and no requirement is missed.",
        f"{value}. Delivery requires {duration} days and {price}, while preserving every mandatory condition.",
        f"{value}, a compliant {duration}-day alternative whose recorded price is {price}.",
        f"{value}. The proposal satisfies all requirements at {price} over {duration} days.",
        f"{value}; both its {duration}-day timing and {price} price fit the complete criteria.",
        f"{value}. All mandatory checks pass, with {price} required across {duration} days.",
        f"{value}, requiring {price} and a {duration}-day window without violating any condition.",
        f"{value}. The full requirement set remains satisfied; cost is {price} and duration {duration} days.",
        f"{value}; implementation spans {duration} days, totals {price}, and preserves complete compliance.",
        f"{value}. Every stated condition is covered by this {price}, {duration}-day proposal.",
        f"{value}, whose schedule is {duration} days and whose compliant budget is {price}.",
        f"{value}. Nothing in the requirements is omitted; the plan takes {duration} days at {price}.",
        f"{value}; recorded duration is {duration} days, recorded spend is {price}, and all constraints pass.",
        f"{value}. This alternative remains fully eligible with {duration} days of work and {price} in cost.",
        f"{value}, satisfying the mandatory list while using {price} within a {duration}-day period.",
        f"{value}. Compliance is complete, the schedule is {duration} days, and the amount is {price}.",
        f"{value}; no hard condition fails under its {duration}-day schedule and {price} cost.",
        f"{value}. The option stays inside every requirement with a {price} total and {duration} days to finish.",
        f"{value}, a fully qualifying proposal recorded at {price} with a duration of {duration} days.",
    )


def _planning_invalid_records(option: str, cost: str) -> tuple[str, ...]:
    """Return full non-qualifying alternatives with varied failure syntax."""

    value = f"{{{option}}}"
    price = f"${{{cost}}}"
    return (
        f"{value}; it costs {price}, takes 5 days, and misses one mandatory requirement.",
        f"{value}. At {price} over 5 days, one non-negotiable condition remains unmet.",
        f"{value}, priced at {price} for five days but failing a required condition.",
        f"{value}; the five-day plan totals {price} and lacks one mandatory element.",
        f"{value}. One hard requirement fails despite a recorded cost of {price} and a five-day schedule.",
        f"{value}; budget use is {price}, completion takes five days, and one condition is missing.",
        f"{value}. Delivery requires five days and {price}, while one mandatory check does not pass.",
        f"{value}, a non-compliant five-day alternative with a price of {price}.",
        f"{value}. The proposal costs {price} across five days and leaves one requirement unsatisfied.",
        f"{value}; neither its five-day timing nor its missing condition clears the complete criteria at {price}.",
        f"{value}. A mandatory check fails in this {price}, five-day proposal.",
        f"{value}, requiring {price} and five days while violating one non-negotiable condition.",
        f"{value}. The requirement set is incomplete; cost is {price} and duration five days.",
        f"{value}; implementation spans five days, totals {price}, and omits a compulsory item.",
        f"{value}. One stated condition is not covered by this {price}, five-day proposal.",
        f"{value}, whose schedule is five days and whose non-compliant budget is {price}.",
        f"{value}. A required element is absent, and the plan takes five days at {price}.",
        f"{value}; recorded duration is five days, recorded spend is {price}, and one constraint fails.",
        f"{value}. This alternative is not fully eligible after five days of work and {price} in cost.",
        f"{value}, missing a mandatory item while using {price} within a five-day period.",
        f"{value}. Compliance is incomplete, the schedule is five days, and the amount is {price}.",
        f"{value}; one hard condition fails under its five-day schedule and {price} cost.",
        f"{value}. The option misses one requirement with a {price} total and five days to finish.",
        f"{value}, a disqualified proposal recorded at {price} with a duration of five days.",
    )


@dataclass(frozen=True)
class _SurfaceRule:
    key: str
    pattern: re.Pattern[str]
    variants: tuple[str, ...]
    literal_sources: tuple[str, ...] = ()


def _literal_rule(
    key: str,
    sources: tuple[str, ...],
    variants: tuple[str, ...],
) -> _SurfaceRule:
    return _SurfaceRule(
        key=key,
        pattern=re.compile(
            "(?:" + "|".join(re.escape(source) for source in sources) + ")",
            flags=re.IGNORECASE,
        ),
        variants=variants,
        literal_sources=tuple(source.casefold() for source in sources),
    )


