_REPETITION_RULES: dict[str, tuple[_SurfaceRule, ...]] = {
    task: tuple(
        _literal_rule(key, sources, variants)
        for key, sources, variants in (
            *REPETITION_LITERAL_RESERVOIRS.get(task, ()),
            *SECOND_PASS_LITERAL_RESERVOIRS.get(task, ()),
            *THIRD_PASS_LITERAL_RESERVOIRS.get(task, ()),
        )
    )
    for task in sorted(
        set(REPETITION_LITERAL_RESERVOIRS)
        | set(SECOND_PASS_LITERAL_RESERVOIRS)
        | set(THIRD_PASS_LITERAL_RESERVOIRS)
    )
}

# Some provenance and safety facts are shared by several families.  Their
# wording belongs to the source surface, not to a task-specific card, so the
# same semantic rewrite must remain available wherever that literal occurs.
_GLOBAL_REPETITION_RULES: tuple[_SurfaceRule, ...] = tuple(
    _literal_rule(key, sources, variants)
    for task in sorted(_REPETITION_RULES)
    for key, sources, variants in (
        *REPETITION_LITERAL_RESERVOIRS.get(task, ()),
        *SECOND_PASS_LITERAL_RESERVOIRS.get(task, ()),
        *THIRD_PASS_LITERAL_RESERVOIRS.get(task, ()),
    )
)


