_GRAMMAR_IMPERATIVE_FRAME = re.compile(
    r"\bPlease keep in mind that\s+(?=[A-Z])",
)
_GRAMMAR_CONNECTOR_CAPITAL = re.compile(
    r"\b(?P<connector>Then|First,|For timing,|For ownership,|"
    r"To test the answer independently,)\s+(?P<word>[A-Z][a-z]+)"
)
_GRAMMAR_AN_WORD = re.compile(
    r"\ba\s+(?P<word>uncertain|overwhelming|index|average|encryption|"
    r"appointment|equipment|account|unknown|injury)\b",
    flags=re.IGNORECASE,
)


def _clean_surface_grammar(text: str) -> str:
    """Repair deterministic junction errors introduced by card composition."""

    for pattern, replacement in _GRAMMAR_LITERAL_REPLACEMENTS:
        text = pattern.sub(replacement, text)
    text = _GRAMMAR_IMPERATIVE_FRAME.sub("", text)
    text = _GRAMMAR_CONNECTOR_CAPITAL.sub(
        lambda match: f"{match.group('connector')} {match.group('word').lower()}",
        text,
    )
    text = _GRAMMAR_AN_WORD.sub(lambda match: f"an {match.group('word')}", text)
    text = re.sub(r" {2,}", " ", text)
    text = re.sub(r"(?<=[a-z0-9'\"])\.(?=[A-Z])", ". ", text)
    text = re.sub(
        r"\bnote that (?P<word>A(?= second\b)|[A-Z][a-z]+)",
        lambda match: "note that " + match.group("word").lower(),
        text,
    )
    text = re.sub(
        r"\bnote that A (?P<noun>reverse|division|backward)\b",
        lambda match: "note that a " + match.group("noun"),
        text,
    )
    text = re.sub(
        r"\b(?:the|a|an) (?P<article>the|a|an)\b",
        lambda match: match.group("article"),
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"\s+[—-]\s*\.", ".", text)
    text = re.sub(r"(?<!\.)\.\.(?!\.)", ".", text)
    text = re.sub(
        r"(?<=[.!?]) (?P<letter>[a-z])",
        lambda match: " " + match.group("letter").upper(),
        text,
    )
    return text


def _same_pattern_rules(
    key: str,
    pattern: re.Pattern[str],
    variants: tuple[str, ...],
    *,
    applications: int,
) -> tuple[_SurfaceRule, ...]:
    """Apply one semantic rewrite to several occurrences in the same turn."""

    return tuple(
        _SurfaceRule(f"{key}-{index + 1}", pattern, variants)
        for index in range(applications)
    )


